{
  "name": "opencode-status-tracker",
  "version": "1.0.9",
  "description": "Real-time status bar plugin for OpenCode: cache hit rate, token usage, cost, latency and model info in the sidebar footer.",
  "type": "module",
  "exports": {
    ".": "./dist/index.js",
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build && npm run typecheck"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "status",
    "cache",
    "token",
    "cost",
    "latency",
    "monitoring"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/LINoone516/opencode-status-tracker"
  },
  "engines": {
    "opencode": ">=1.4.3"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.18",
    "@opentui/core": ">=0.1.97",
    "@opentui/solid": ">=0.1.97",
    "solid-js": "^1.9.11"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.18",
    "@opentui/core": ">=0.1.97",
    "@opentui/solid": ">=0.1.97",
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.0",
    "solid-js": "^1.9.11",
    "typescript": "^5.7.0"
  }
}
